            self.reserved_15 = self._io.read_bits_int_be(1) != 0
            self.dtmf_send = self._io.read_bits_int_be(1) != 0
            self.reserved_13_4 = self._io.read_bits_int_be(10)
            self.cni_frame = self._io.read_bits_int_be(1) != 0
            self.reserved_2_0 = self._io.read_bits_int_be(3)
