            self.start = self._io.read_bytes(1)
            if not self.start == b"\x61":
                raise kaitaistruct.ValidationNotEqualError(b"\x61", self.start, self._io, u"/types/frame/seq/0")
            self.len_data = self._io.read_u2be()
            self.type = KaitaiStream.resolve_enum(HrV3000.PacketType, self._io.read_u1())
            _on = self.type
            if _on == HrV3000.PacketType.ccp:
                pass
                self._raw_data = self._io.read_bytes(self.len_data)
                _io__raw_data = KaitaiStream(BytesIO(self._raw_data))
                self.data = HrV3000.ControlPacket(_io__raw_data, self, self._root)
                self.data._read()
            elif _on == HrV3000.PacketType.decp:
                pass
                self._raw_data = self._io.read_bytes(self.len_data)
                _io__raw_data = KaitaiStream(BytesIO(self._raw_data))
