    class VersionString(ReadWriteKaitaiStruct):
        """VERSTRING answer (Length >= 7).
        
        .. seealso::
           HR_V3000 manual v1.2, 5.9.2, p.21; A.1, p.22
        """
        def __init__(self, _io=None, _parent=None, _root=None):
            super(HrV3000.VersionString, self).__init__(_io)
            self._parent = _parent
            self._root = _root

        def _read(self):
            self.text = (self._io.read_bytes_full()).decode(u"ASCII")
            self._dirty = False


        def _fetch_instances(self):
            pass


        def _write__seq(self, io=None):
            super(HrV3000.VersionString, self)._write__seq(io)
            self._io.write_bytes((self.text).encode(u"ASCII"))
            if not self._io.is_eof():
                raise kaitaistruct.ConsistencyError(u"text", 0, self._io.size() - self._io.pos())


        def _check(self):
            self._dirty = False



